{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket encryption not configured",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled, leaving data at rest unencrypted."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block missing",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "There is no aws_s3_bucket_public_access_block resource associated with this bucket, meaning public access is not explicitly restricted."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 versioning disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket, which prevents recovery from accidental deletion or overwrites."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not configured, reducing visibility into who accesses the bucket and what actions are performed."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket                  = aws_s3_bucket.data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "data" {
  bucket        = aws_s3_bucket.data.id
  target_bucket = aws_s3_bucket.data.id # In production, point to a separate log bucket
  target_prefix = "logs/"
}",
  "fix_summary": "Added server-side encryption configuration using AES256. Added a public access block to prevent unintended public exposure. Enabled versioning for data protection. Configured access logging (pointing to itself as a placeholder for minimal change, though a dedicated log bucket is recommended)."
}
